import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        try (PrintWriter w = new PrintWriter(new FileWriter("q11.txt"))) {
            w.println("1 2");
            w.println("3 4");
        }
        int t = 0;
        try (Scanner s = new Scanner(new File("q11.txt"))) {
            while (s.hasNextInt()) {
                t += s.nextInt();
            }
        }
        System.out.println(t);
    }
}

